import uuid
from django.conf import settings
from django.db import models
class SecurityAssessment(models.Model):
    class Status(models.TextChoices): PENDING='pending','Pending'; COMPLETED='completed','Completed'; FAILED='failed','Failed'
    id=models.UUIDField(primary_key=True,default=uuid.uuid4,editable=False); user=models.ForeignKey(settings.AUTH_USER_MODEL,on_delete=models.CASCADE,related_name='security_assessments'); submitted_url=models.URLField(max_length=2048); normalized_url=models.URLField(max_length=2048); final_url=models.URLField(max_length=2048,blank=True); authorization_confirmed=models.BooleanField(default=False); authorization_confirmed_at=models.DateTimeField(null=True,blank=True); status=models.CharField(max_length=20,choices=Status.choices,default='pending'); overall_score=models.PositiveSmallIntegerField(null=True,blank=True); risk_level=models.CharField(max_length=20,blank=True); confidence_score=models.PositiveSmallIntegerField(null=True,blank=True); completeness_percentage=models.PositiveSmallIntegerField(null=True,blank=True); target_scope=models.JSONField(default=dict); transport_findings=models.JSONField(default=dict); header_findings=models.JSONField(default=dict); cookie_findings=models.JSONField(default=dict); form_findings=models.JSONField(default=dict); mixed_content_findings=models.JSONField(default=dict); exposure_findings=models.JSONField(default=dict); public_file_findings=models.JSONField(default=dict); cors_findings=models.JSONField(default=dict); technology_findings=models.JSONField(default=dict); findings=models.JSONField(default=list); recommendations=models.JSONField(default=list); positive_findings=models.JSONField(default=list); unavailable_checks=models.JSONField(default=list); check_results=models.JSONField(default=dict); methodology_version=models.CharField(max_length=20,blank=True); ai_security_report=models.TextField(blank=True); failure_stage=models.CharField(max_length=50,blank=True); error_category=models.CharField(max_length=50,blank=True); error_message=models.TextField(blank=True); stage_durations_ms=models.JSONField(default=dict); created_at=models.DateTimeField(auto_now_add=True); completed_at=models.DateTimeField(null=True,blank=True)
    class Meta: ordering=['-created_at']
